package store

import (
	"bytes"
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"errors"
	"regexp"
	"time"

	"mikugate/internal/certassets"
	"mikugate/internal/ingress"
)

// RefreshManagedCertificate changes only TLS assets for the exact management
// DNS identity AND old leaf binding. UUIDs, client passwords, proxy credentials,
// listeners and REALITY material are never regenerated by certificate renewal.
// The coordinator must hold the control write lease while this transaction runs.
func (s *Store) RefreshManagedCertificate(asset *certassets.Asset, expectedLeaf string) (int, error) {
	if asset == nil || !asset.Summary().ChainVerified || !asset.Summary().KeyMatched || !regexp.MustCompile(`^[a-f0-9]{64}$`).MatchString(expectedLeaf) {
		return 0, certassets.ErrCertificate
	}
	cert, key := asset.PEM()
	defer clear(key)
	rechecked, err := certassets.Validate(asset.Summary().Hostname, cert, key)
	if err != nil || rechecked.Summary().LeafSHA256 != asset.Summary().LeafSHA256 {
		return 0, certassets.ErrCertificate
	}
	rows, err := s.db.Query("SELECT exit_id FROM managed_ingress LIMIT 4097")
	if err != nil {
		return 0, err
	}
	ids := []string{}
	for rows.Next() {
		var id string
		if err = rows.Scan(&id); err != nil {
			rows.Close()
			return 0, err
		}
		ids = append(ids, id)
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return 0, err
	}
	if len(ids) > 4096 {
		return 0, errors.New("入口证书更新超出当前预算")
	}
	type update struct {
		id     string
		sealed []byte
	}
	pending := []update{}
	for _, id := range ids {
		material, _, exists, err := s.Managed(id)
		if err != nil || !exists {
			return 0, errors.New("入口证书更新无法认证现有材料")
		}
		plan, err := ingress.ManagedPlanFor(material.Request)
		if err != nil {
			return 0, err
		}
		if !plan.NeedsCertificate || material.Request.ServerName != asset.Summary().Hostname {
			continue
		}
		block, _ := pem.Decode(material.CertificatePEM)
		if block == nil || block.Type != "CERTIFICATE" {
			return 0, certassets.ErrCertificate
		}
		leaf, err := x509.ParseCertificate(block.Bytes)
		if err != nil {
			return 0, certassets.ErrCertificate
		}
		digest := sha256.Sum256(leaf.Raw)
		if hex.EncodeToString(digest[:]) != expectedLeaf {
			continue
		}
		if bytes.Equal(material.CertificatePEM, cert) && bytes.Equal(material.PrivateKeyPEM, key) {
			continue
		}
		material.CertificatePEM = bytes.Clone(cert)
		material.PrivateKeyPEM = bytes.Clone(key)
		if _, err = material.Render(); err != nil {
			return 0, err
		}
		raw, err := json.Marshal(material)
		if err != nil {
			return 0, err
		}
		vault, err := s.secretVault()
		if err != nil {
			clear(raw)
			return 0, err
		}
		label, err := s.managedLabel(id)
		if err != nil {
			clear(raw)
			return 0, err
		}
		sealed, err := vault.Seal(label, raw)
		clear(raw)
		clear(material.PrivateKeyPEM)
		if err != nil {
			return 0, err
		}
		pending = append(pending, update{id, sealed})
	}
	if len(pending) == 0 {
		return 0, nil
	}
	tx, err := s.db.Begin()
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()
	for _, item := range pending {
		result, err := tx.Exec("UPDATE managed_ingress SET sealed=?,updated_at=? WHERE exit_id=?", item.sealed, time.Now().UTC().Format(time.RFC3339Nano), item.id)
		if err != nil {
			return 0, err
		}
		count, err := result.RowsAffected()
		if err != nil || count != 1 {
			return 0, errors.New("入口证书事务绑定发生变化")
		}
		if err = event(tx, "info", "ingress.certificate_refreshed", "已更新同域名受管TLS证书，保留客户端身份与出口绑定", item.id); err != nil {
			return 0, err
		}
	}
	if err = tx.Commit(); err != nil {
		return 0, err
	}
	return len(pending), nil
}
